<script lang="ts">
  import {replaceContent} from "../../ui/replacement.ts";
  import {surface,mist} from '../../ui/surface.ts';
  import {scrollArea} from '../../ui/scroll.ts';
  import type { DecisionView, SavePermission } from '@ash/shared';
  import { onMount } from 'svelte';
  import Card from './Card.svelte';
  let {decisions,api,onChanged,onThread,onRule,onClose,onSettings}:{decisions:DecisionView[];api:<T>(path:string,body?:object)=>Promise<T>;onChanged:()=>Promise<void>;onThread:(id:string)=>void;onRule:(rule:SavePermission)=>void;onClose:()=>void;onSettings:()=>void}=$props();
  let list:HTMLDivElement;
  function switchTab(next:typeof tab){void replaceContent(list,()=>{tab=next;},{resize:false});}
  let closeButton:HTMLButtonElement;onMount(()=>closeButton?.focus());
  let tab=$state<'Pending'|'Snoozed'|'History'>('Pending');
  function tabKey(event:KeyboardEvent,name:typeof tab){const tabs=['Pending','Snoozed','History'] as const;if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const index=tabs.indexOf(name);const next=tabs[event.key==='Home'?0:event.key==='End'?2:(index+(event.key==='ArrowRight'?1:-1)+3)%3];switchTab(next);document.getElementById(`decision-${next}`)?.focus();}
  const visible=$derived(decisions.filter(d=>tab==='Pending'?d.status==='pending':tab==='Snoozed'?d.status==='snoozed':['resolved','cancelled'].includes(d.status)).sort((a,b)=>tab==='History'?Date.parse(b.updatedAt)-Date.parse(a.updatedAt):(a.dueAt?Date.parse(a.dueAt):Infinity)-(b.dueAt?Date.parse(b.dueAt):Infinity)||Date.parse(a.createdAt)-Date.parse(b.createdAt)));
</script>
<main class="decision-page" aria-label="Decisions" data-testid="decisions-page" use:surface={{dense:true}} transition:mist={{role:"large"}}><div class="surface-content"><header><h1>Decisions</h1><div class="page-actions"><button onclick={onSettings} class="ash-button">Settings</button><button bind:this={closeButton} aria-label="Back to chat" onclick={onClose} class="ash-button">Back to chat</button></div></header><div class="tabs" role="tablist" aria-label="Decision views">{#each ['Pending','Snoozed','History'] as name}<button role="tab" id={`decision-${name}`} aria-controls="decision-list" aria-selected={tab===name} tabindex={tab===name?0:-1} onkeydown={event=>tabKey(event,name as typeof tab)} onclick={()=>switchTab(name as typeof tab)} class="ash-button">{name}</button>{/each}</div><div bind:this={list} use:scrollArea class="list" role="tabpanel" id="decision-list" aria-labelledby={`decision-${tab}`} tabindex="0">{#each visible as decision(decision.id)}<Card {decision} {api} {onChanged} {onThread} {onRule}/>{:else}<p class="empty">No {tab.toLowerCase()} Decisions.</p>{/each}</div></div></main>
<style>
.decision-page{flex:1;min-width:0;background:color-mix(in srgb,var(--control) 35%,transparent);display:flex;flex-direction:column;overflow:hidden;padding:28px 36px;color:var(--text);animation:none}header{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-shrink:0}h1{font:525 1.4rem/1.25 var(--font);margin:0}.page-actions{display:flex;gap:8px}button{font:inherit;border:0;background:transparent;color:var(--text);padding:9px 10px;border-radius:5px;cursor:pointer;font-size:.9rem}.tabs{display:flex;gap:24px;border-bottom:1px solid var(--divider);margin-top:24px;flex-shrink:0}.tabs button{padding:12px 0;border-bottom:2px solid transparent;border-radius:0}.tabs button[aria-selected=true]{border-bottom-color:var(--accent);font-weight:525}.list{overflow:auto;flex:1;min-height:0;padding:12px 0;scrollbar-gutter:stable}.list :global(.decision-card){max-width:880px;margin:0 0 16px}.empty{font-size:1rem;color:var(--text);margin:24px 0}@media(max-width:800px){.decision-page{padding:24px 18px}header{align-items:flex-start;flex-wrap:wrap}}@keyframes enter{from{opacity:.5;transform:translateY(3px)}to{opacity:1;transform:translateY(0)}}@media(prefers-reduced-motion:reduce){.decision-page{animation:none}}
</style>
